                    anyhow::anyhow!("--commander must be SEAT:CARD, got '{spec}'")
                })?;
                let seat: u8 = seat.trim().parse().map_err(|_| {
                    anyhow::anyhow!("--commander seat must be a number, got '{seat}'")
                })?;
                let name = name.trim();
