            ManaColor::Black => "black",
            ManaColor::Red => "red",
            ManaColor::Green => "green",
            ManaColor::Colorless => "colorless",
        }
    }

    /// Mana symbol as printed.
    pub fn symbol(self) -> &'static str {
        match self {
            ManaColor::White => "{W}",
            ManaColor::Blue => "{U}",
            ManaColor::Black => "{B}",
            ManaColor::Red => "{R}",
