        .battlefield(P0, &[card("Jaddi Offshoot")])
        .main(P0, Step::PrecombatMain)
        .build();
    let jaddi = battlefield_card(&game, P0, card("Jaddi Offshoot"));
    let mut log = Vec::new();
    assert!(run_until(
        &mut game,
        &mut log,
